import React, { forwardRef, useMemo } from "react";
import {
    TouchableOpacity,
    Text,
    StyleSheet,
    ViewStyle,
    TextStyle,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { WaveDotsLoader } from "@/components/loaders/wave-dots-loader";
import { ShineGradientWrapper } from "@/components/layout/shine-gradient-wrapper";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";
import type { IconName } from "@/lib/utils";

export interface ActionButtonProps {
    title: string;
    variant?: "primary" | "secondary";
    size?: "sm" | "default" | "lg";
    fullWidth?: boolean;
    roundness?: "default" | "full" | "sm" | "none";
    icon?: IconName | string;
    iconPosition?: "pre" | "post";
    isLoading?: boolean;
    disabled?: boolean;
    onPress?: () => void;
    style?: ViewStyle;
    textStyle?: TextStyle;
    withShine?: boolean;
    hasGradient?: boolean;
    GradientColors?: [string, string, ...string[]];
}

export const ActionButton = forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    ActionButtonProps
>(
    (
        {
            title,
            variant = "primary",
            size = "default",
            fullWidth = true,
            roundness = "default",
            icon,
            iconPosition = "post",
            isLoading = false,
            disabled = false,
            onPress,
            style,
            textStyle,
            withShine = false,
            hasGradient = false,
            GradientColors = ["#8870e6", "#5f84e0", "#5f84e0"],
        },
        ref,
    ) => {
        const theme = useTheme();
        const styles = useMemo(() => createStyles(theme), [theme]);
        const isDisabled = disabled || isLoading;
        const isWrapped = (withShine || hasGradient) && !isDisabled;

        const radiusMap = {
            default: 16,
            full: 9999,
            sm: 8,
            none: 0,
        };
        const activeRadius = radiusMap[roundness];
        const iconSize = size === "sm" ? 14 : size === "lg" ? 20 : 18;

        const sizeStyles = {
            sm: styles.sizeSm,
            default: styles.sizeDefault,
            lg: styles.sizeLg,
        }[size];

        const textSizeStyles = {
            sm: styles.textSm,
            default: styles.textDefault,
            lg: styles.textLg,
        }[size];

        const buttonStyles = [
            styles.baseButton,
            sizeStyles,
            { borderRadius: activeRadius },
            fullWidth ? styles.fullWidth : styles.fitContent,
            variant === "primary"
                ? styles.primaryButton
                : styles.secondaryButton,
            isDisabled && styles.disabledButton,
            isLoading && styles.loadingButton,
            isWrapped && styles.wrappedOverride,
            hasGradient && !isDisabled && styles.gradientOverride,
            style,
        ];

        const textStylesArray = [
            styles.baseText,
            textSizeStyles,
            variant === "primary" ? styles.primaryText : styles.secondaryText,
            isDisabled && styles.disabledText,
            textStyle,
        ];

        const activeColor = isDisabled
            ? theme.foregroundMuted
            : variant === "primary"
              ? theme.primaryForeground
              : theme.secondaryForeground;

        const buttonContent = (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.9}
                disabled={isDisabled}
                onPress={onPress}
                style={buttonStyles}
            >
                {isLoading ? (
                    <WaveDotsLoader />
                ) : (
                    <>
                        {icon && iconPosition === "pre" && (
                            <DynamicIcon
                                name={icon as string}
                                size={iconSize}
                                color={activeColor}
                            />
                        )}
                        <Text style={textStylesArray}>{title}</Text>
                        {icon && iconPosition === "post" && (
                            <DynamicIcon
                                name={icon as string}
                                size={iconSize}
                                color={activeColor}
                            />
                        )}
                    </>
                )}
            </TouchableOpacity>
        );

        if (isWrapped) {
            return (
                <ShineGradientWrapper
                    colors={GradientColors}
                    isShining={withShine}
                    hasGradient={hasGradient}
                    style={[
                        styles.shineWrapper,
                        { borderRadius: activeRadius },
                        fullWidth ? styles.fullWidth : styles.fitContent,
                        size === "sm"
                            ? { marginBottom: 0 }
                            : { marginBottom: 12 },
                    ]}
                >
                    {buttonContent}
                </ShineGradientWrapper>
            );
        }

        return buttonContent;
    },
);
ActionButton.displayName = "ActionButton";

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        baseButton: {
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "center",
            borderWidth: 1,
        },
        fullWidth: {
            width: "100%",
        },
        fitContent: {
            alignSelf: "flex-start",
        },
        sizeSm: {
            minHeight: 36,
            paddingHorizontal: 12,
            gap: 6,
            marginBottom: 0,
        },
        sizeDefault: {
            minHeight: 48,
            paddingHorizontal: 16,
            gap: 8,
            marginBottom: 12,
        },
        sizeLg: {
            minHeight: 56,
            paddingHorizontal: 24,
            gap: 8,
            marginBottom: 12,
        },
        primaryButton: {
            backgroundColor: theme.primary,
            borderColor: "transparent",
            shadowColor: theme.primary,
            shadowOffset: { width: 0, height: 2 },
            shadowOpacity: 0.2,
            shadowRadius: 4,
            elevation: 2,
        },
        secondaryButton: {
            backgroundColor: theme.secondary,
            borderColor: theme.secondaryForeground,
        },
        disabledButton: {
            backgroundColor: theme.surfaceMuted,
            borderColor: "transparent",
            elevation: 0,
            shadowOpacity: 0,
        },
        loadingButton: {
            opacity: 0.8,
        },
        wrappedOverride: {
            marginBottom: 0,
        },
        gradientOverride: {
            backgroundColor: "transparent",
            borderColor: "transparent",
            elevation: 0,
            shadowOpacity: 0,
        },
        shineWrapper: {
            overflow: "hidden",
        },
        baseText: {
            fontWeight: "700",
        },
        textSm: {
            fontSize: 12,
        },
        textDefault: {
            fontSize: 13,
        },
        textLg: {
            fontSize: 15,
        },
        primaryText: {
            color: theme.primaryForeground,
        },
        secondaryText: {
            color: theme.secondaryForeground,
        },
        disabledText: {
            color: theme.foregroundMuted,
        },
    });

import React, { useMemo } from "react";
import {
    View,
    Text,
    TouchableOpacity,
    StyleSheet,
    ViewStyle,
} from "react-native";
import { Controller, FieldValues, UseControllerProps } from "react-hook-form";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";
import type { IconName } from "@/lib/utils";

export interface CheckboxOption {
    value: string;
    title: string;
    subtitle?: string;
    icon?: IconName | string;
    badge?: string;
    cornerBadge?: string;
    disabled?: boolean;
}

export interface CheckboxCardProps {
    option: CheckboxOption;
    isSelected: boolean;
    onToggle: (value: string) => void;
    checkboxPosition?: "left" | "right";
    style?: ViewStyle;
}

export function CheckboxCard({
    option,
    isSelected,
    onToggle,
    checkboxPosition = "right",
    style,
}: CheckboxCardProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const handlePress = () => {
        if (option?.disabled) return;
        onToggle(option?.value);
    };

    const CheckboxSquare = (
        <View
            style={[
                styles.square,
                isSelected ? styles.squareSelected : styles.squareUnselected,
                option?.disabled && styles.disabledOpacity,
            ]}
        >
            {isSelected && (
                <DynamicIcon
                    name="Check"
                    size={14}
                    strokeWidth={3}
                    color={theme.primaryForeground}
                />
            )}
        </View>
    );

    return (
        <TouchableOpacity
            activeOpacity={0.75}
            onPress={handlePress}
            disabled={option?.disabled}
            style={[
                styles.card,
                isSelected ? styles.cardSelected : styles.cardUnselected,
                option?.disabled && styles.disabledOpacity,
                style,
            ]}
        >
            {option?.cornerBadge && (
                <View style={styles.cornerBadge}>
                    <Text style={styles.cornerBadgeText}>
                        {option?.cornerBadge}
                    </Text>
                </View>
            )}

            <View style={styles.leftZone}>
                {checkboxPosition === "left" && (
                    <View style={styles.leftCheckbox}>{CheckboxSquare}</View>
                )}

                {option?.icon && (
                    <View
                        style={[
                            styles.iconContainer,
                            isSelected
                                ? styles.iconContainerSelected
                                : styles.iconContainerUnselected,
                        ]}
                    >
                        <DynamicIcon
                            name={option?.icon as string}
                            size={20}
                            color={
                                isSelected
                                    ? theme.primary
                                    : theme.foregroundMuted
                            }
                        />
                    </View>
                )}

                <View style={styles.titleContainer}>
                    <View style={styles.titleRow}>
                        <Text
                            style={[
                                styles.titleText,
                                isSelected && styles.titleTextSelected,
                            ]}
                            numberOfLines={1}
                        >
                            {option?.title}
                        </Text>
                        {option?.badge && (
                            <View style={styles.inlineBadge}>
                                <Text style={styles.inlineBadgeText}>
                                    {option?.badge}
                                </Text>
                            </View>
                        )}
                    </View>
                    {option?.subtitle && (
                        <Text style={styles.subtitleText} numberOfLines={1}>
                            {option?.subtitle}
                        </Text>
                    )}
                </View>
            </View>

            {checkboxPosition === "right" && CheckboxSquare}
        </TouchableOpacity>
    );
}

export interface CheckboxProps {
    checked: boolean;
    onCheckedChange: (checked: boolean) => void;
    label?: string;
    description?: string;
    disabled?: boolean;
    style?: ViewStyle;
}

export function Checkbox({
    checked,
    onCheckedChange,
    label,
    description,
    disabled = false,
    style,
}: CheckboxProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const handlePress = () => {
        if (disabled) return;
        onCheckedChange(!checked);
    };

    return (
        <TouchableOpacity
            activeOpacity={0.75}
            onPress={handlePress}
            disabled={disabled}
            style={[
                styles.simpleCheckboxContainer,
                disabled && styles.disabledOpacity,
                style,
            ]}
        >
            <View
                style={[
                    styles.square,
                    checked ? styles.squareSelected : styles.squareUnselected,
                ]}
            >
                {checked && (
                    <DynamicIcon
                        name="Check"
                        size={14}
                        strokeWidth={3}
                        color={theme.primaryForeground}
                    />
                )}
            </View>

            {(label || description) && (
                <View style={styles.simpleTextContainer}>
                    {label && <Text style={styles.simpleLabel}>{label}</Text>}
                    {description && (
                        <Text style={styles.simpleDescription}>
                            {description}
                        </Text>
                    )}
                </View>
            )}
        </TouchableOpacity>
    );
}

export interface CheckboxGroupProps {
    options: CheckboxOption[];
    values: string[];
    onValuesChange: (values: string[]) => void;
    checkboxPosition?: "left" | "right";
    label?: string;
    error?: string;
    style?: ViewStyle;
}

export function CheckboxGroup({
    options,
    values = [],
    onValuesChange,
    checkboxPosition = "right",
    label,
    error,
    style,
}: CheckboxGroupProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const handleToggle = (value: string) => {
        if (values.includes(value)) {
            onValuesChange(values.filter((v) => v !== value));
        } else {
            onValuesChange([...values, value]);
        }
    };

    return (
        <View style={[styles.groupContainer, style]}>
            {label && <Text style={styles.groupLabel}>{label}</Text>}
            {options?.map((option) => (
                <CheckboxCard
                    key={option?.value}
                    option={option}
                    isSelected={values.includes(option?.value)}
                    onToggle={handleToggle}
                    checkboxPosition={checkboxPosition}
                />
            ))}
            {error && <Text style={styles.errorText}>{error}</Text>}
        </View>
    );
}

export interface ControlledCheckboxGroupProps<
    T extends FieldValues,
> extends UseControllerProps<T> {
    options: CheckboxOption[];
    checkboxPosition?: "left" | "right";
    label?: string;
}

export function ControlledCheckboxGroup<T extends FieldValues>({
    control,
    name,
    options,
    checkboxPosition,
    label,
}: ControlledCheckboxGroupProps<T>) {
    return (
        <Controller
            control={control}
            name={name}
            render={({ field: { onChange, value }, fieldState: { error } }) => (
                <CheckboxGroup
                    options={options}
                    values={Array.isArray(value) ? value : []}
                    onValuesChange={onChange}
                    checkboxPosition={checkboxPosition}
                    label={label}
                    error={error?.message}
                />
            )}
        />
    );
}

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        groupContainer: {
            width: "100%",
            marginBottom: 12,
        },
        groupLabel: {
            fontSize: 12,
            fontWeight: "500",
            color: theme.foregroundMuted,
            marginBottom: 8,
            marginLeft: 4,
        },
        card: {
            position: "relative",
