            minHeight: 60,
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "space-between",
            padding: 16,
            marginBottom: 12,
            borderRadius: 16,
            borderWidth: 1,
        },
        cardUnselected: {
            backgroundColor: theme.surface,
            borderColor: theme.border,
        },
        cardSelected: {
            backgroundColor: `${theme.primary}0D`, // 5% Opacity
            borderColor: theme.primary,
        },
        disabledOpacity: {
