            fontWeight: "900",
            color: theme.background,
        },
        leftZone: {
            flexDirection: "row",
            alignItems: "center",
            flex: 1,
            marginRight: 12,
        },
        leftCheckbox: {
            marginRight: 14,
        },
        iconContainer: {
            height: 44,
            width: 44,
            alignItems: "center",
            justifyContent: "center",
            marginRight: 14,
            borderRadius: 12,
        },
        iconContainerSelected: {
            backgroundColor: `${theme.primary}1A`,
        },
        iconContainerUnselected: {
            backgroundColor: theme.surfaceMuted,
        },
        titleContainer: {
            flex: 1,
            justifyContent: "center",
        },
        titleRow: {
            flexDirection: "row",
            alignItems: "center",
            gap: 8,
            flexWrap: "wrap",
        },
        titleText: {
            fontSize: 14,
            fontWeight: "700",
            color: theme.foreground,
        },
        titleTextSelected: {
            color: theme.primary,
        },
        inlineBadge: {
            paddingHorizontal: 8,
            paddingVertical: 2,
            borderRadius: 6,
            backgroundColor: `${theme.primary}1A`,
        },
        inlineBadgeText: {
            fontSize: 10,
            fontWeight: "700",
            color: theme.primary,
        },
        subtitleText: {
            fontSize: 12,
            color: theme.foregroundMuted,
            marginTop: 2,
        },
        square: {
            height: 20,
            width: 20,
            alignItems: "center",
            justifyContent: "center",
            borderRadius: 6,
            borderWidth: 2,
        },
        squareUnselected: {
            borderColor: theme.border,
            backgroundColor: "transparent",
        },
        squareSelected: {
            borderColor: theme.primary,
            backgroundColor: theme.primary,
        },
        simpleCheckboxContainer: {
            flexDirection: "row",
            alignItems: "center",
            gap: 12,
            paddingVertical: 8,
        },
        simpleTextContainer: {
            flex: 1,
            justifyContent: "center",
        },
        simpleLabel: {
            fontSize: 14,
            fontWeight: "600",
            color: theme.foreground,
        },
        simpleDescription: {
            fontSize: 12,
