import React, { useMemo, useState } from "react";
import {
    View,
    Text,
    Platform,
    ViewStyle,
    StyleSheet,
    ScrollView,
    TouchableOpacity,
} from "react-native";
import { Controller, FieldValues, UseControllerProps } from "react-hook-form";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface DropdownOption {
    label: string;
    value: string;
}

export interface DropdownSelectProps {
    label?: string;
    options: DropdownOption[];
    selectedValue: string;
    onSelect: (value: string) => void;
    error?: string;
    placeholder?: string;
    style?: ViewStyle;
    zIndex?: number;
}

export function DropdownSelect({
    label,
    options,
    selectedValue,
    onSelect,
    error,
    placeholder = "Select an option",
    style,
    zIndex = 10,
}: DropdownSelectProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);
    const [isOpen, setIsOpen] = useState(false);

    const handleSelect = (val: string) => {
        onSelect(val);
        setIsOpen(false);
    };

    const selectedLabel = useMemo(() => {
        const selected = options?.find((opt) => opt?.value === selectedValue);
        return selected ? selected.label : "";
    }, [selectedValue, options]);

    const dynamicZIndex = isOpen ? 999 : zIndex;

    return (
        <View
            style={[
                styles.container,
                {
                    zIndex: dynamicZIndex,
                    // Android requires elevation alongside zIndex to layer above following views
                    elevation:
                        Platform.OS === "android" ? dynamicZIndex : undefined,
                },
                style,
            ]}
        >
            {label && <Text style={styles.label}>{label}</Text>}

            <TouchableOpacity
                activeOpacity={0.8}
                onPress={() => setIsOpen(!isOpen)}
                style={[
                    styles.triggerButton,
                    isOpen && styles.triggerButtonActive,
                    error && styles.triggerButtonError,
                ]}
            >
                <Text
                    style={[
                        styles.triggerText,
                        !selectedLabel && styles.placeholderText,
                    ]}
                    numberOfLines={1}
                >
                    {selectedLabel || placeholder}
                </Text>
                <DynamicIcon
                    name={isOpen ? "ChevronUp" : "ChevronDown"}
                    size={20}
                    color={theme.foregroundMuted}
                    strokeWidth={3}
                />
            </TouchableOpacity>

            {isOpen && options?.length > 0 && (
                <View style={styles.dropdownMenu}>
                    <ScrollView
                        nestedScrollEnabled
                        bounces={false}
                        style={styles.scrollArea}
                        keyboardShouldPersistTaps="handled"
                    >
                        {options?.map((option, index) => {
                            const isSelected = selectedValue === option.value;
                            return (
                                <TouchableOpacity
                                    key={option.value}
                                    activeOpacity={0.7}
                                    onPress={() => handleSelect(option.value)}
                                    style={[
                                        styles?.optionItem,
                                        index !== options.length - 1 &&
                                            styles.optionBorder,
                                        isSelected && styles.optionItemSelected,
                                    ]}
                                >
                                    <Text
                                        style={[
                                            styles.optionText,
                                            isSelected &&
                                                styles.optionTextSelected,
                                        ]}
                                    >
                                        {option.label}
                                    </Text>
                                    {isSelected && (
                                        <DynamicIcon
                                            name="Check"
                                            size={18}
                                            color={theme.primary}
                                            strokeWidth={3}
                                        />
                                    )}
                                </TouchableOpacity>
                            );
                        })}
                    </ScrollView>
                </View>
            )}

            {error && <Text style={styles.errorText}>{error}</Text>}
        </View>
    );
}

export interface ControlledDropdownSelectProps<
    T extends FieldValues,
> extends UseControllerProps<T> {
    label?: string;
    options: DropdownOption[];
    placeholder?: string;
    zIndex?: number;
}

export function ControlledDropdownSelect<T extends FieldValues>({
    control,
    name,
    label,
    options,
    placeholder,
    zIndex,
}: ControlledDropdownSelectProps<T>) {
    return (
        <Controller
            control={control}
            name={name}
            render={({ field: { onChange, value }, fieldState: { error } }) => (
                <DropdownSelect
                    label={label}
                    options={options}
                    selectedValue={value || ""}
                    onSelect={onChange}
                    error={error?.message}
                    placeholder={placeholder}
                    zIndex={zIndex}
                />
            )}
        />
    );
}

