export interface HomeHeaderProps {
    inMainWrapper?: boolean;
    title?: string;
    hasNotifications?: boolean;
    onItemPress?: (route: string) => void;
    homeHeaderOptions: any;
}

export function HomeHeader({
    inMainWrapper = true,
    title = "App Name",
    hasNotifications = true,
    onItemPress,
    style,
    homeHeaderOptions,
    ...props
}: HomeHeaderProps) {
    const insets = useSafeAreaInsets();
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const dotOpacity = useSharedValue(0.3);

    useEffect(() => {
        if (hasNotifications) {
            dotOpacity.value = withRepeat(
                withSequence(
                    withTiming(1, {
                        duration: 1000,
                        easing: Easing.inOut(Easing.ease),
                    }),
                    withTiming(0.3, {
                        duration: 1000,
                        easing: Easing.inOut(Easing.ease),
                    }),
                ),
                -1,
                true,
            );
        } else {
            dotOpacity.value = 0;
        }
    }, [hasNotifications]);

    const animatedDotStyle = useAnimatedStyle(() => ({
        opacity: dotOpacity.value,
    }));

    return (
        <View
            style={[
                styles.container,
                { marginTop: inMainWrapper ? 0 : insets.top + 20 },
                style,
            ]}
            {...props}
        >
            <View style={styles.innerRow}>
                <View style={styles.brandingGroup}>
                    <View style={styles.logoContainer}>
                        {/* logo component here */}
                    </View>
                    <Text
                        style={[
                            styles.titleText,
                            { color: homeHeaderOptions?.textColor },
                        ]}
                    >
                        {title}
                    </Text>
                </View>

                {/* Actions */}
                <View style={styles.actionsGroup}>
                    <TouchableOpacity
                        activeOpacity={0.9}
                        onPress={() => onItemPress("/notifications")}
                        style={styles.actionButton}
                    >
                        <DynamicIcon name="Bell" size={26} color={"#ffffff"} />
                        <Animated.View
                            style={[styles.notificationDot, animatedDotStyle]}
                        />
                    </TouchableOpacity>

                    <TouchableOpacity
                        activeOpacity={0.8}
                        onPress={() => onItemPress("/profile")}
                        style={styles.actionButton}
                    >
                        <DynamicIcon name="User" size={26} color={"#ffffff"} />
                    </TouchableOpacity>
                </View>
            </View>
        </View>
    );
}

