}

export function MainWrapper({
    children,
    homeHeader = false,
    navigatorHeader = true,
    heading,
    topSpacing,
    fullScreen = false,
    navigatorOptions,
    bottomSpacing = 10,
    homeHeaderOptions,
    style,
    a,
}: MainWrapperProps) {
    const router = useRouter();
    const insets = useSafeAreaInsets();

    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const safeBottomPadding = Math.min(insets.bottom, bottomSpacing);

    const handleHomeHeaderRedirects = (route: string) => {
        router.push(route);
    };

    return (
        <View
            style={[
                styles.container,
                {
                    paddingTop: fullScreen
                        ? 0
                        : topSpacing
                          ? insets.top + 30
                          : insets.top + 10,
                    paddingBottom: fullScreen ? 0 : safeBottomPadding,
                },
                style,
            ]}
            {...props}
        >
            <View style={styles.inner}>
                {homeHeader ? (
                    <HomeHeader
                        inMainWrapper
                        homeHeaderOptions={homeHeaderOptions}
                        title="Zudhan"
