                    <NavigatorHeader
                        title={heading ?? ""}
                        inMainWrapper
                        navigatorOptions={navigatorOptions}
                    />
                ) : heading ? (
                    <NavigatorHeader
                        title={heading ?? ""}
                        inMainWrapper
                        haveBackButton={false}
                        navigatorOptions={navigatorOptions}
                    />
                ) : null}

                {children}
            </View>
        </View>
    );
}

