import React, { useMemo } from "react";
import {
    Text,
    TouchableOpacity,
    View,
    StyleSheet,
    ViewStyle,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface SectionWrapperProps {
    children: React.ReactNode;
    type?: "default" | "bordered";
    title?: string;
    showInfoIcon?: boolean;
    onInfoPress?: () => void;
    rightTitle?: string;
    rightType?: "text" | "navigate" | "chip";
    rightAction?: () => void;
    style?: ViewStyle;
    contentStyles: ViewStyle;
}

export function SectionWrapper({
    children,
    type = "default",
    title,
    showInfoIcon = false,
    onInfoPress,
    rightTitle,
    rightType = "text",
    rightAction,
    style,
    contentStyles,
}: SectionWrapperProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const renderInfoIcon = () => {
        if (!showInfoIcon && !onInfoPress) return null;

        const IconElement = (
            <DynamicIcon
                name="Info"
                size={16}
                color={theme.foregroundMuted}
                style={styles.infoIcon}
            />
        );

        if (onInfoPress) {
            return (
                <TouchableOpacity
                    activeOpacity={0.7}
                    onPress={onInfoPress}
                    hitSlop={10}
                >
                    {IconElement}
                </TouchableOpacity>
            );
        }
        return IconElement;
    };

    return (
        <View style={[styles.container, style]}>
            {/* Header Row (Outside the border) */}
            <View style={styles.headerRow}>
                <View style={styles.titleGroup}>
                    {title && <Text style={styles.title}>{title}</Text>}
                    {renderInfoIcon()}
                </View>

                {/* Right Action */}
                {rightTitle &&
                    (rightType === "text" ? (
                        <Text style={styles.rightText}>{rightTitle}</Text>
                    ) : (
                        <TouchableOpacity
                            style={[
                                styles.actionButton,
                                rightType === "chip" && styles.actionButtonChip,
                            ]}
                            onPress={rightAction}
                            activeOpacity={0.7}
                            disabled={!rightAction}
                        >
                            <Text style={styles.rightText}>{rightTitle}</Text>
                            <DynamicIcon
                                name="ChevronRight"
                                size={12}
                                color={theme.foregroundMuted}
                            />
                        </TouchableOpacity>
                    ))}
            </View>

            {/* Content (Only the children receive the border and padding) */}
            <View
                style={[
                    type === "bordered" && styles.borderedContent,
                    contentStyles,
                ]}
            >
                {children}
            </View>
        </View>
    );
}

const createStyles = (theme: ThemeTokens) =>
