import React, { useEffect, useMemo } from "react";
import { View, StyleSheet, ViewStyle } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import Animated, {
    useSharedValue,
    useAnimatedStyle,
    withRepeat,
    withTiming,
    Easing,
    withDelay,
} from "react-native-reanimated";

export interface ShineGradientWrapperProps {
    colors: [string, string, ...string[]];
    children: React.ReactNode;
    style?: ViewStyle;
    isShining?: boolean;
    hasGradient?: boolean;
}

export function ShineGradientWrapper({
    colors,
    children,
    style,
    isShining = false,
    hasGradient = false,
}: ShineGradientWrapperProps) {
    const styles = useMemo(() => createStyles(), []);
    const shimmerPosition = useSharedValue(-300);

    useEffect(() => {
        if (isShining) {
            shimmerPosition.value = withRepeat(
                withDelay(
                    1500,
                    withTiming(400, {
                        duration: 1200,
                        easing: Easing.inOut(Easing.ease),
                    }),
                ),
                -1,
                false,
            );
        }
    }, [isShining]);

    const shimmerStyle = useAnimatedStyle(() => {
        return {
            transform: [{ translateX: shimmerPosition.value }],
        };
    });

    return (
        <View style={[styles.container, style]}>
            <LinearGradient
                colors={hasGradient ? colors : ["transparent", "transparent"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.gradientContainer}
            >
                {isShining && (
                    <Animated.View
                        style={[StyleSheet.absoluteFill, shimmerStyle]}
                        pointerEvents="none"
                    >
                        <LinearGradient
                            colors={[
                                "rgba(255,255,255,0)",
                                "rgba(255,255,255,0.4)",
                                "rgba(255,255,255,0)",
                            ]}
                            start={{ x: 0, y: 0 }}
                            end={{ x: 1, y: 0 }}
                            style={[
                                StyleSheet.absoluteFill,
                                styles.shimmerGradient,
                            ]}
                        />
                    </Animated.View>
                )}

                <View style={styles.content}>{children}</View>
            </LinearGradient>
        </View>
    );
}

const createStyles = () =>
    StyleSheet.create({
        container: {
            overflow: "hidden",
            position: "relative",
        },
        gradientContainer: {
            width: "100%",
            justifyContent: "center",
        },
        shimmerGradient: {
            width: 150,
            transform: [{ skewX: "-20deg" }],
        },
        content: {
            zIndex: 10,
            width: "100%",
            justifyContent: "center",
        },
    });

import React, { useRef, forwardRef, useMemo } from "react";
import {
    Text,
    View,
    Animated,
    PanResponder,
    LayoutChangeEvent,
    ViewProps,
    StyleSheet,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface SlideToActionProps extends ViewProps {
    text?: string;
    onComplete: () => void;
}

const KNOB_SIZE = 54;
const TRACK_PADDING = 6;

export const SlideToAction = forwardRef<
    React.ElementRef<typeof View>,
    SlideToActionProps
>(
    (
        { text = "Swipe right to get started", onComplete, style, ...props },
        ref,
    ) => {
        const theme = useTheme();
        const styles = useMemo(() => createStyles(theme), [theme]);

        const pan = useRef(new Animated.Value(0)).current;
        const maxSlideRef = useRef(0);

        const panResponder = useRef(
            PanResponder.create({
                onStartShouldSetPanResponder: () => true,
                onPanResponderMove: (_, gestureState) => {
                    const maxSlide = maxSlideRef.current;
                    if (
                        maxSlide > 0 &&
                        gestureState.dx > 0 &&
                        gestureState.dx <= maxSlide
                    ) {
                        pan.setValue(gestureState.dx);
                    }
                },
                onPanResponderRelease: (_, gestureState) => {
                    const maxSlide = maxSlideRef.current;
                    if (maxSlide > 0 && gestureState.dx > maxSlide * 0.75) {
